 * @param tableName - The name of the table for which the color is being determined.
 * @returns The corresponding background color class as a string.
 */
export function getRowColor(color: string | undefined): string {
  if (color === 'RED') return 'bg-danger-red';
  if (color === 'GREY') return 'bg-grey-4';
  if (color === 'WHITE') return 'bg-white';
  if (color === 'ORANGE') return 'bg-orange';
  if (color === 'YELLOW') return 'bg-yellow';
  if (color === 'RED_BELL') return 'bg-grey-4';

  return 'bg-white';
}
