import { DateTime } from 'luxon';

/**
 * Converts a date from a specific timezone to UTC.
 * @param date - The date to convert.
 * @param timezone - The timezone of the date.
 * @returns The date in UTC.
 */
export function convertToUTC(
  date: string | Date,
  timezone: string,
): Date | string {
  const dateTime =
    typeof date === 'string'
      ? DateTime.fromISO(date, { zone: timezone })
      : DateTime.fromJSDate(date, { zone: timezone });

  if (!dateTime.isValid) {
    throw new Error('Invalid date format');
  }

  // Check for the specific conditions (1900-01 and 1899-12)
  const value = dateTime.toISO();
  if (value.includes('1900-01') || value.includes('1899-12')) {
    return '';
  }

  return dateTime.toFormat('yyyy-MM-dd HH:mm:ss');
}
/**
 * Converts a date from UTC to a specific timezone.
 * @param date - The date in UTC to convert.
 * @param timezone - The target timezone.
 * @returns The date in the specified timezone.
 */
export function convertFromUTC(date: string | Date, timezone: string): string {
  const dateTime =
    typeof date === 'string'
      ? DateTime.fromISO(date, { zone: 'utc' })
      : DateTime.fromJSDate(date, { zone: 'utc' });

  if (!dateTime.isValid) {
    throw new Error('Invalid date format');
  }

  return dateTime.setZone(timezone).toFormat('yyyy-MM-dd HH:mm:ss.SSS');
}

import { Logout } from '@mesx/common-ui-lib';
import { createRouter, createWebHistory } from 'vue-router';
import alertScreenView from '../modules/alert-screen/views/alert-screen-view.vue';
import advancedFilter from '../modules/filter-config/views/advanced-filter.vue';
import { useProfileStore } from '../modules/picking-screen/store/user-auth-store.ts';
