import pickingUi from '../modules/picking-screen/views/PickingUi.vue';
import Unauthorized from '../modules/picking-screen/views/Unauthorized.vue';
import loadingComponent from '../modules/picking-screen/views/loading.vue';
import ServerConfigurationView from '../modules/user-management/views/ServerConfigurationView.vue';
import appLogger from '../utils/logger/app-logger.ts';

const appRedirectUri = import.meta.env.APP_REDIRECT_URI;
let appBasePath: string | undefined;
if (appRedirectUri) {
  const parts = appRedirectUri.split('/');
  appBasePath = parts.pop();
}
// Define routes
const routes = [
  {
    component: ServerConfigurationView,
    meta: { requiresAuth: true, title: 'Server Configuration' },
    name: 'ServerConfiguration',
    path: '/serverconfig',
    props: true,
  },
  {
    component: Logout,
    name: 'Logout',
    path: '/logout',
    props: {
      onLoginAgain: (): void => {
        const profileStore = useProfileStore();
        profileStore.initializeAuthentication();
        router.push('/picking-ui');
      },
    },
  },
  {
    component: PickingScreenView,
    meta: { requiresAuth: true, title: 'TPA Picking Monitoring' },
    name: 'pickingScreen',
    path: '/picking-ui/tpa-ui',
  },
  {
    component: PickingScreenView,
    meta: { requiresAuth: true, title: 'TPA Picking Monitoring' },
    name: 'PickingSharedGroupFilterBoard',
    path: '/picking-ui/tpa-ui/:groupName',
    props: true,
  },
  {
    component: alertScreenView,
    meta: { requiresAuth: true, title: 'Alert Picking Monitoring' },
    name: 'AlertSharedGroupFilterBoard',
    path: '/picking-ui/alert-ui/:groupName',
    props: true,
  },
  {
    component: advancedFilter,
    meta: { requiresAuth: true, title: 'Picking Filter Layout' },
    name: 'Picking Filter Layout',
    path: '/picking-ui/tpa-ui/filter-layout',
    props: true,
  },
  {
    component: advancedFilter,
    meta: { requiresAuth: true, title: 'Alert Filter Layout' },
    name: 'Alert Filter Layout',
    path: '/picking-ui/alert-ui/filter-layout',
    props: true,
  },
  {
    component: pickingUi,
    meta: { requiresAuth: true, title: 'TPA Picking Monitoring' },
    name: 'pickingUi',
    path: '/picking-ui',
  },
  {
    component: alertScreenView,
    meta: { requiresAuth: true, title: 'Alert picking monitoring' },
    name: 'AlertScreenView',
    path: '/picking-ui/alert-ui',
  },
  {
    component: Unauthorized,
    name: 'Unauthorized',
    path: `/${appBasePath}/unauthorized`,
  },
  {
    component: loadingComponent,
    name: 'LoadingComponent',
    path: '/picking-ui/loading',
  },
];

// Create the router
const router = createRouter({
  history: createWebHistory(),
  routes,
});

router.beforeEach(async (to, _from, next) => {
  if (to.meta.title) {
    document.title = `MESX.0 - ${to.meta.title as string}`;
  }
  const userAuth = useProfileStore();
  if (to.meta.requiresAuth) {
    try {
      await userAuth.authenticateUser();
      const user = await userAuth.getUser();
      if (user) {
        await userAuth.fetchUserAttributes();
        await userAuth.authorizeUser();
      } else {
        console.error('User not found');
        return next(`/${appBasePath}/unauthorized`); // Return is added here
      }
      return next();
    } catch (error) {
      appLogger.error(`Error during authentication or authorization: ${error}`);
      return next(`/${appBasePath}/unauthorized`); // Return is added here
    }
  } else {
    return next(); // Explicit return for non-authenticated routes
  }
});

export default router;

import { ref, reactive } from 'vue';

/**
 * Retrieves the value of VALUEQ from localStorage.
 * @returns The parsed value of VALUEQ.
 */
function getValueQ(): string {
  const storedValue = window.localStorage.getItem('VALUEQ');
  const parsedValue = storedValue ? JSON.parse(storedValue) : true;
  return parsedValue;
}

/**
 * Retrieves the value of VALUEE from localStorage.
 * @returns The parsed value of VALUEE.
 */
function getValueE(): string {
  const storedValue = window.localStorage.getItem('VALUEE');
  const parsedValue = storedValue ? JSON.parse(storedValue) : true;
  return parsedValue;
}

const state = reactive({
  valueE: ref(JSON.parse(getValueE())),
  valueQ: ref(JSON.parse(getValueQ())),
});

/**
 * Sets the value of VALUEQ and updates localStorage.
 * @param value - The value to be set for VALUEQ.
 */
function setValueQ(value: unknown): void {
  state.valueQ = value;
  window.localStorage.setItem('VALUEQ', JSON.stringify(value));
}

/**
 * Sets the value of VALUEE and updates localStorage.
 * @param value - The value to be set for VALUEE.
 */
function setValueE(value: unknown): void {
  state.valueE = value;
  window.localStorage.setItem('VALUEE', JSON.stringify(value));
}

// Export necessary functions and data
export { state, setValueQ, setValueE, getValueQ, getValueE };

