  sfgWkCtr: Array<string>,
  material: Array<string>,
  sourceLoc: Array<string>,
  destinationLoc: Array<string>,
  pickingStatus: Array<string>,
  customStatus: Array<string>,
  cstr: Array<string>,
  otbDlr: Array<string>,
  tpaNumber: Array<string>,
  tpaCde: Array<string>,
  endProductionTimeType: string,
  pickingTimeScale: string,
  pickingTimeMax: number,
  pickingTimeMin: number,
  endProductionDate: string,
  startPrepTimeType: string,
  endPrepTimeType: string,
  truckDepartureType: string,
  startPreparationTime: string,
  endPrepDate: string,
  truckDepDate: string,
  promiseDate: string,
  alert: string,
  rescheduled: string,
  huCurrentStorageLocation: Array<string>,
  isAlert?: boolean,
  status?: string,
  alertLevel?: string,
  pickingOrderIDSelected?: Array<string>,
): Promise<PickingOrder> => {
  const userAttributesStore = useUserAttributesStore();
  const plant = Number(userAttributesStore.userAttributes.plant);

  const parameters: Record<
    string,
    string | number | boolean | undefined | Array<string>
  > = {
    alert,
    alertLevel,
    customStatus,
    customer: cstr,
    destinationLocation: destinationLoc,
    endPrepTimeType,
    endProdTimeType: endProductionTimeType,
    endProductionTime: endProductionDate,
    huCurrentStorageLocation,
    material,
    outbound: otbDlr,
    pickingStatus,
    pickingTimeMax,
    pickingTimeMin,
    pickingTimeScale,
    promiseTime: promiseDate,
    rescheduled,
    sfgWorkcenter: sfgWkCtr,
    sourceLocation: sourceLoc,
    startPrepTimeType,
    tpaBeginPreparation: startPreparationTime,
    tpaCode: tpaCde,
    tpaEndPreparation: endPrepDate,
    tpaNumber,
    truckDepartureTime: truckDepDate,
    truckDepartureType,
    workcenter: wkCtr,
  };
  if (pickingOrderIDSelected?.length === 1) {
    const response: AxiosResponse<PickingOrder> = await axiosInstance.get(
      `${pickingBackendBaseUrl}/picking/${plant}/${pickingOrderIDSelected[0]}`,
      {
        headers: {
          authorization: `Bearer ${token}`,
        },
      },
    );

    return response.data;
  }
  const response: AxiosResponse<PickingOrder> = await axiosInstance.post(
    `${pickingBackendBaseUrl}/picking/getOrdersByCriteria/${plant}`,
    {
      isAlert,
      status,
    },
    {
      headers: {
        authorization: `Bearer ${token}`,
      },
      params: parameters,
    },
  );

  return response.data;
};
