export const getUserPreferences = async (
  userId: string,
  appName: string,
): Promise<any> => {
  const userAttributesStore = useUserAttributesStore();
  const plant = Number(userAttributesStore.userAttributes.plant);
  const response: AxiosResponse<
    Array<UserPreference>,
    Array<UserPreference>
  > = await axios.get(
    `${umeBaseUrl}/user-preference/${plant}/${userId}/${appName}`,
    {
      headers: {
        authorization: `Bearer ${token}`,
      },
    },
  );
  const { data } = response;
  let columnsPreferences = undefined as UserPreference | undefined;
  const uniqueObjects: Record<string, boolean> = {};
  const filterPreferencesList = [] as Array<UserPreference>;
  if (data !== undefined) {
    // Start from the last index and move backwards
    const length = data?.length ?? 0;
    for (let index = length - 1; index >= 0; index -= 1) {
      if (
        data[index].action === 'HIDE_COL' &&
        columnsPreferences === undefined
      ) {
        // Found the last hidden column
        columnsPreferences = data[index];
      }
      for (let innerIndex = length - 1; innerIndex >= 0; innerIndex -= 1) {
        const item = data[innerIndex];
        if (item.action === 'FILTER') {
          const objectsToAdd = item.object
            .split(';')
            .filter((object) => !uniqueObjects[object]);
          for (const object of objectsToAdd) {
            uniqueObjects[object] = true;
            filterPreferencesList.unshift({
              action: item.action,
              addData: item.addData,
              appName,
              object,
              plant,
              user: { userId },
            });
          }
        }
      }
    }
  }

  if (columnsPreferences === null || columnsPreferences === undefined) {
    columnsPreferences = { addData: '' } as UserPreference;
  }
  return { columnsPreferences, filterPreferencesList };
};

