const axiosInstance: AxiosInstance = axios.create({});
// Helper function to validate date formats
/**
 * Validates whether the given value is a valid date string.
 * @param value - The value to validate. This can be any type, but the function checks specifically if it's a string representing a date.
 * @returns - Returns true if the value is a valid date string; otherwise, false.
 */
function isDateValid(value: unknown): boolean {
  if (typeof value !== 'string') return false;
  // Numeric Check
  const numericRegex = /^\d+$/;
  if (numericRegex.test(value)) return false;
  const isoDate = DateTime.fromISO(value);
  const httpDate = DateTime.fromHTTP(value);
  const rfc2822Date = DateTime.fromRFC2822(value);
  // Custom date formats regex
  const customDateRegexes = [
    /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}(\.\d{1,7})?$/, // 'yyyy-MM-dd HH:mm:ss.SSSSSSS'
    /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}(\.\d{1,3})?$/, // 'yyyy-MM-dd HH:mm:ss.SSS'
    /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/, // 'yyyy-MM-dd HH:mm:ss'
    /^\d{2}-[A-Za-z]{3}-\d{4}$/, // 'dd-MMM-yyyy'
    /^\d{4}-\d{2}-\d{2}$/, // 'yyyy-MM-dd'
    /^[A-Za-z]{3}, \d{2} [A-Za-z]{3} \d{4} \d{2}:\d{2}:\d{2} GMT$/, // RFC 2822 date format, case-insensitive
    /^[A-Za-z]{3}, \d{2} [A-Za-z]{3} \d{4} \d{2}:\d{2}:\d{2} GMT$/, // HTTP date format, case-insensitive
    /^\d{2}-\d{2}-\d{4} \d{2}:\d{2}:\d{2}$/, // 'MM-dd-yyyy HH:mm:ss'
  ];

  const isCustomDate = customDateRegexes.some((regex) => regex.test(value));

  return (
    isoDate.isValid || httpDate.isValid || rfc2822Date.isValid || isCustomDate
  );
}

type DataObject = Record<string, unknown>;
type Data = DataObject | Array<DataObject>;

// Transform dates to server's timezone
/**
 * Transforms all valid date strings in the data to the specified server timezone.
 * @param data - The data containing date strings to transform. This can be an object or an array of objects.
 * @param timezone - The target timezone in which to transform the date strings.
 * @returns - The transformed data with dates in the server's timezone.
 */
// Transform dates to server's timezone
function transformDatesToServerTimezone<T extends Data>(
  data: T,
  timezone: string,
): T {
  if (Array.isArray(data)) {
    return data.map((item) =>
      transformDatesToServerTimezone(item, timezone),
    ) as T;
  }

  if (data && typeof data === 'object') {
    const transformedData = { ...data } as DataObject;

    for (const key of Object.keys(transformedData)) {
      const value = transformedData[key] as string;

      if (isDateValid(value)) {
        if (
          (value.includes('1900-01') && value.endsWith('000Z')) ||
          value.includes('1899-12')
        ) {
          transformedData[key] = '';
        } else {
          const date = DateTime.fromISO(value).setZone(timezone);
          transformedData[key] = date.toFormat('yyyy-MM-dd HH:mm:ss'); // Returns formatted date string
        }
      } else if (value && typeof value === 'object') {
        transformedData[key] = transformDatesToServerTimezone(
          value as DataObject,
          timezone,
        );
      }
    }

    return transformedData as T;
  }

  return data;
}

// Transform dates from server's timezone to local timezone
/**
 * Transforms all valid date strings in the data from the server's timezone to the local timezone.
 * @param data - The data containing date strings to transform. This can be an object or an array of objects.
 * @param timezone - The server's timezone from which to transform the date strings.
 * @returns - The transformed data with dates in the local timezone.
 */
// Transform dates from server's timezone to local timezone
function transformDatesFromServerTimezone<T extends Data>(
  data: T,
  timezone: string,
): T {
  if (Array.isArray(data)) {
    return data.map((item) =>
      transformDatesFromServerTimezone(item, timezone),
    ) as T;
  }

  if (data && typeof data === 'object') {
    const transformedData = { ...data } as DataObject;

    for (const key of Object.keys(transformedData)) {
      const value = transformedData[key] as string;

      if (isDateValid(value)) {
        // Parse in the server's timezone, then convert to local time
        const date = DateTime.fromFormat(value, 'yyyy-MM-dd HH:mm:ss', {
          zone: timezone,
        }).toUTC();
        if (date.isValid) {
          transformedData[key] = date.toISO();
        } else {
          const dateAlt = DateTime.fromFormat(value, 'yyyy-MM-dd', {
            zone: timezone,
          }).toUTC();
          transformedData[key] = dateAlt.toISO();
        }
      } else if (value && typeof value === 'object') {
        transformedData[key] = transformDatesFromServerTimezone(
          value as DataObject,
          timezone,
        );
      }
    }

    return transformedData as T;
  }

  return data;
}

// Request interceptor to transform dates before sending requests
axiosInstance.interceptors.request.use(
  async (
    config: InternalAxiosRequestConfig,
  ): Promise<InternalAxiosRequestConfig> => {
    const userAttributesStore = useProfileStore();
    const modifiedConfig = { ...config }; // Clone the config object
    const plantTimezone = userAttributesStore.userAttributes.timezone ?? 'utc';
    if (modifiedConfig) {
      modifiedConfig.params = transformDatesFromServerTimezone(
        modifiedConfig.params,
        plantTimezone,
      );
    }
    return modifiedConfig; // Return the modified clone
  },
  (error) => {
    // Use an Error object to reject the promise
    return Promise.reject(new Error(error.message || 'Request error'));
  },
);

// Response interceptor to transform dates after receiving responses
axiosInstance.interceptors.response.use(
  async (response: AxiosResponse): Promise<AxiosResponse> => {
    const userAttributesStore = useProfileStore();
    const plantTimezone = userAttributesStore.userAttributes.timezone ?? 'utc';
    if (response.data) {
      response.data = transformDatesToServerTimezone(
        response.data,
        plantTimezone,
      );
    }
    return response;
  },
  (error) => {
    // Use an Error object to reject the promise
    return Promise.reject(new Error(error.message || 'Response error'));
  },
);

