export const useAlertTableStore = defineStore({
  actions: {
    handleDateChange(newDate: string, isValidDate: boolean) {
      // Only update the date and completed status if the date is valid
      this.dateTimeCompleted[0] = isValidDate; // Mark as completed only if valid
      if (isValidDate) {
        this.date = newDate; // Update the date only if valid
      }
    },
    handleTimeChange(newTime: string, isValidTime: boolean) {
      this.dateTimeCompleted[1] = isValidTime; // Mark as completed only if valid

      if (isValidTime) {
        this.time = newTime; // Update the time only if valid
      }
    },
    resetDateTimeCompleted() {
      this.dateTimeCompleted = [false, false];
    },
  },
  id: 'alertTable',
  state: () => {
    const userAttributesStore = useUserAttributesStore();
    const plantTimezone = userAttributesStore.userAttributes.timezone ?? 'utc';
    const now = DateTime.now().setZone(plantTimezone);
    return {
      date: ref(now.toFormat('yyyy/MM/dd')),
      time: ref('00:00'),
      dateTimeCompleted: [false, false], // DateTimeCompleted[0] = date validity, dateTimeCompleted[1] = time validity
    };
  },
});

