/**
 *
 * @param value to be tested
 * @returns  Returns true if the string is numeric, otherwise false.
 */
export const usePickingTableStore = defineStore({
  actions: {
    closePreferencesDialog(tableName: string) {
      if (tableName === 'picking') {
        this.showPickingPreferencesDialog = false;
      }
      if (tableName === 'alert') {
        this.showAlertPreferencesDialog = false;
      }
    },
    async closeShopOrders() {
      this.handleSelectedRows();
      const result = await api.closeShopOrders(
        this.selectedShopOrdersIdsString,
      );
      return result;
    },

    async countNotReadedComment(pickingOrderId: Array<string>) {
      const result = await api.countNotReadedComment(pickingOrderId);
      return result;
    },
    filterColumns() {
      this.pickingFilteredColumns = this.pickingColumns.filter(
        (column) => column.visible,
      );

      this.alertFilteredColumns = this.alertColumns.filter(
        (column) => column.visible,
      );
    },
    async getPickingOrderById(id: string) {
      this.order = await api.getPickingOrderById(id);
      return this.order;
    },
    async getPlantById(): Promise<Plant> {
      const userAttributesStore = useUserAttributesStore();
      this.plant = await api.getPlantById(
        Number(userAttributesStore.userAttributes.plant),
      );
      return this.plant;
    },

    handleSelectedRows() {
      this.selectedShopOrdersIdsString = this.selectedRows
        .map((row: { pickingOrderId: string }) => row.pickingOrderId)
        .join(';');
    },

    hideColumns(columnsToHide: Array<string>) {
      if (!Array.isArray(columnsToHide)) return;

      // Group columns by table for efficient lookup
      const tableColumnMapping = {
        alert: this.alertColumns,
        picking: this.pickingColumns,
      };

      // Parse the columns to hide into a lookup map
      const columnsToHideMap = new Map<string, Set<string>>();
      for (const columnName of columnsToHide) {
        const [name, table] = columnName.split('_');
        if (!columnsToHideMap.has(table)) {
          columnsToHideMap.set(table, new Set());
        }
        columnsToHideMap.get(table)?.add(name);
      }

      // Update visibility for each column list
      for (const [table, columnList] of Object.entries(tableColumnMapping)) {
        const hideSet = columnsToHideMap.get(table) || new Set();
        for (const column of columnList) {
          column.visible = !hideSet.has(column.name);
        }
      }
    },
    openPreferencesDialog(tableName: string) {
      if (tableName === 'picking') {
        this.showPickingPreferencesDialog = true;
      }
      if (tableName === 'alert') {
        this.showAlertPreferencesDialog = true;
      }
    },
    async saveComment(comment: CommentSaveRequest): Promise<void> {
      try {
        await api.saveComment(comment);
        // Optionally, you can add more logic here, such as updating the state or notifying the user
      } catch (error) {
        console.error('Failed to save comment:', error);
        // Optionally, handle the error, such as showing an error message to the user
      }
    },
    setpickingFiltredRows(data: Array<TableRow> | TableRow) {
      this.pickingFiltredRows = data;
    },

    updateColumnIndexes(columnsToHide: Array<string>) {
      if (Array.isArray(columnsToHide) && columnsToHide.length > 0) {
        for (const index of columnsToHide) {
          if (index) {
            const [table, name, columnIndex] = index.split('_');
            const columnList =
              table === 'ip' ? this.pickingColumns : this.alertColumns;
            const column = columnList.find((col) => col.name === name);
            if (column) {
              column.index = Number(columnIndex);
            }
          }
          // Reorder the columns by index
          this.pickingColumns.sort((a, b) => a.index - b.index);
          this.alertColumns.sort((a, b) => a.index - b.index);
        }
      }
    },

    updateColumnsPreferences(preference: UserPreference) {
      if (
        preference.addData !== '' &&
        preference.addData !== undefined &&
        preference.addData !== null
      ) {
        const columnsToHide = preference?.addData.split(';');
        this.updateColumnIndexes(columnsToHide);
        this.hideColumns(columnsToHide);
      }
      this.filterColumns();
    },
  },
