import { FilterConfig } from '../../filter-config/dtos/filter-config.dto.ts';
import {
  createFilterConfig,
  getFilterConfigByPlant,
  updateFilterConfig,
  getFilterByUserAndGroup,
} from '../../filter-config/services/api';
import * as api from '../service/api.ts';
import { usePickingTableStore } from './picking-table-store.ts';
import { useUserAttributesStore } from './user-profile-store.ts';

const useFiltersStore = defineStore({
  actions: {
    addDataToSelectedList(addData: string, selectedList: Array<string>) {
      const addDataArray = addData.split(';');
      for (const data of addDataArray) {
        const trimmedData = data.trim();

        if (trimmedData !== '' && !selectedList.includes(trimmedData)) {
          selectedList.push(trimmedData);
        }
      }
    },
    async applyUserPreferences(
      tableName: string,
      appName: string,
      groupName?: string,
    ) {
      const pickingTableStore = usePickingTableStore();
      pickingTableStore.userId = localStorage.getItem('userId') ?? 'undefined';
      let userId: string | null = localStorage.getItem('userId');
      if (!userId) {
        await new Promise<void>((resolve) => {
          const interval = setInterval(() => {
            userId = localStorage.getItem('userId');
            if (userId) {
              clearInterval(interval);
              resolve();
            }
          }, 100);
        });
      }
      pickingTableStore.userId = userId as string;

      const userProfile = useUserAttributesStore();
      const { plant } = userProfile.userAttributes;

      try {
        const { columnsPreferences } = await api.getUserPreferences(
          pickingTableStore.userId,
          appName,
        );
        pickingTableStore.updateColumnsPreferences(columnsPreferences);

        if (groupName) {
          const groupPreference = await getFilterByUserAndGroup(
            plant,
            groupName,
            appName,
          );

          if (!groupPreference) {
            console.warn(`No shared filter found for group: ${groupName}`);
            return;
          }

          this.selectedDropdownGroup = groupPreference.groupName;

          const parsedPreferences = this.convertUserCriteriaToPreferences(
            groupPreference.userCriteria,
            tableName,
            appName,
            String(userId),
            Number(plant),
          );

          this.updateFilterPreferences(tableName, parsedPreferences);
        } else {
          const { filterPreferencesList } = await api.getUserPreferences(
            pickingTableStore.userId,
            appName,
          );

          if (filterPreferencesList) {
            this.updateFilterPreferences(tableName, filterPreferencesList);
          }
        }
      } catch (error) {
        console.error('Error applying user preferences:', error);
      }
    },
    convertAttributesToUserCriteria(
      attributes: Array<{ attribute: string; data: Array<string> }>,
      tableName: string,
    ): string {
      return attributes
        .map(({ attribute, data }) => {
          const key = attribute.replace(`_${tableName}`, '');
          return `${key}:${data.join(',')}`;
        })
        .filter((line) => !line.endsWith(':'))
        .join(';');
    },
    convertUserCriteriaToAttributes(
      userCriteria: string,
      tableName: string,
    ): Array<{ attribute: string; data: Array<string> }> {
      if (!userCriteria) return [];
      return userCriteria.split(';').map((criterion) => {
        const [key, values] = criterion.split(':');
        return {
          attribute: `${key}_${tableName}`,
          data: values ? values.split(',') : [],
        };
      });
    },
    convertUserCriteriaToPreferences(
      userCriteria: string,
      tableName: string,
      appName: string,
      userId: string,
      plant: number,
    ): Array<UserPreference> {
      if (!userCriteria) return [];

      return userCriteria
        .split(';')
        .filter((entry) => entry.includes(':'))
        .map((entry) => {
          const [key, value] = entry.split(':');
          return {
            action: 'FILTER',
            addData: value ?? '',
            appName,
            object: `${key}_${tableName}`,
            plant,
            user: { userId },
          };
        });
    },

    async fetchMaterials() {
      try {
        const materialSelection = await api.getMaterialsByPlant();
        this.materialList = Array.isArray(materialSelection)
          ? materialSelection
          : [];
        this.materialListAlert = Array.isArray(materialSelection)
          ? materialSelection
          : [];
      } catch (error) {
        console.error('Failed to fetch materials:', error);
      }
    },
    // Action to fetch picking order data
    async fetchPickingOrderData(_isAlert?: string): Promise<Array<TableRow>> {
      const pickingTableStore = usePickingTableStore();
      const screenName = _isAlert ? 'alert' : 'picking';
      const urlParameters = new URLSearchParams(window.location.search);
      const workcenterParameter = urlParameters.get('workcenter');
      const plantParameter = urlParameters.get('plant');
      const alertLevelParameter = urlParameters.get('alertLevel');
      const workcenterId = sessionStorage.getItem('workcenterId');
      if (workcenterId) {
        this.workCentersSelected = [workcenterId];
      }
      if (workcenterParameter && plantParameter) {
        // â Only take workcenter & plant, ignore other filters
        this.workCentersSelected = [workcenterParameter];
        switch (alertLevelParameter) {
          case 'O': {
            this.alertLevel = 'ORANGE';

            break;
          }
          case 'Y': {
            this.alertLevel = 'YELLOW';

            break;
          }
          case 'R': {
            this.alertLevel = 'RED';

            break;
          }
          default: {
            this.alertLevel = '';
          }
        }
        await this.filterByCriteria(_isAlert ? 'alert' : '501');
      } else {
        const filterSelections = await api.getFiltersSelections(screenName);
        this.workcenterList = filterSelections.workcenter;
        this.sfgWorkcenterList = filterSelections.sfgWorkcenter;
        this.srcLocList = filterSelections.sourceLocation;
