      this.savedPickingTimeMin = this.pickingTimeMin;
      this.savedPickingTimeMax = this.pickingTimeMax;
      const pickingTableStore = usePickingTableStore();
      if (status === '501') {
        isAlert = false;
        // Remove 'CLOSED' custom status for picking screen
        const excludedCustStatuses = new Set(['CLOSED']);
        this.custStatusSelected = this.custStatusSelected.filter(
          (custStatus) => !excludedCustStatuses.has(custStatus),
        );
        const data = await api.searchOrderBycriteria(
          this.workCentersSelected,
          this.sfgWorkCentersSelected,
          this.materialsSelected,
          this.srcLocsSelected,
          this.destLocsSelected,
          this.pickingStatusSelected,
          this.custStatusSelected,
          this.cstr,
          this.otbDlr,
          this.tpaNum,
          this.tpaCodesSelected,
          this.endProdTimeType,
          this.pickingTimeScale,
          this.pickingTimeMax,
          this.pickingTimeMin,
          this.endProdDate,
          this.startPreparationType,
          this.endPreparationType,
          this.truckDepartureType,
          this.startPreparationTime,
          this.endPreparationDate,
          this.truckDepartureDate,
          this.promiseTime,
          this.alert,
          this.rescheduled,
          this.huCurStrLocSelected,
          isAlert,
          status,
          this.alertLevel,
          this.pickingOrderIDSelected,
        );
        pickingTableStore.pickingFiltredRows = Array.isArray(data.shopOrderList)
          ? data.shopOrderList
          : [data.shopOrderList];
        return data.shopOrderList;
      }
      if (status === 'alert') {
        isAlert = true;
        // Remove specific custom statuses
        const excludedCustStatuses = new Set([
          'PIK_CLOSED',
          'PICKED',
          'PALLETIZED',
        ]);
        this.custStatusSelected = this.custStatusSelected.filter(
          (custStatus) => !excludedCustStatuses.has(custStatus),
        );

        // Remove specific picking statuses
        const excludedPickingStatuses = new Set(['CLOSED']);
        this.pickingStatusSelected = this.pickingStatusSelected.filter(
          (custStatus) => !excludedPickingStatuses.has(custStatus),
        );

        const data = await api.searchOrderBycriteria(
          this.workCentersSelected,
          this.sfgWorkCentersSelected,
          this.materialsSelected,
          this.srcLocsSelected,
          this.destLocsSelected,
          this.pickingStatusSelected,
          this.custStatusSelected,
          this.cstr,
          this.otbDlr,
          this.tpaNum,
          this.tpaCodesSelected,
          this.endProdTimeType,
          this.pickingTimeScale,
          this.pickingTimeMax,
          this.pickingTimeMin,
          this.endProdDate,
          this.startPreparationType,
          this.endPreparationType,
          this.truckDepartureType,
          this.startPreparationTime,
          this.endPreparationDate,
          this.truckDepartureDate,
          this.promiseTime,
          this.alert,
          this.rescheduled,
          this.huCurStrLocSelected,
          isAlert,
          undefined,
          this.alertLevel,
        );
        pickingTableStore.alertFiltredRows = Array.isArray(data.shopOrderList)
          ? data.shopOrderList
