    handleRedirectSession(redirectSessionKey: string): void {
      const raw = localStorage.getItem(redirectSessionKey);
      if (!raw) {
        console.warn(`No data found in localStorage for ${redirectSessionKey}`);
        return;
      }
      try {
        const payload: RedirectSessionPayloadDto = JSON.parse(
          raw,
        ) as RedirectSessionPayloadDto;
        if (payload.expiresAt && Date.now() > payload.expiresAt) {
          console.warn(`Redirect session ${redirectSessionKey} expired`);
          localStorage.removeItem(redirectSessionKey);
          return;
        }

        // Write values into filterStore
        this.cstr = payload.data?.selectedCustomers ?? [];
        this.custStatusSelected = payload.data?.selectedCustomStatuses ?? [];
        this.workCentersSelected = payload.data?.selectedWCs ?? [];
        this.materialsSelected = payload.data?.selectedMaterials ?? [];
        this.otbDlr = payload.data?.selectedODs ?? [];
        this.pickingStatusSelected =
          payload.data?.selectedPickingStatuses ?? [];
        this.tpaNum = payload.data?.selectedTPAs ?? [];
        this.pickingOrderIDSelected = payload.data?.selectedWKs ?? [];
        const convertedInterval = this.convertStartEndInterval(
          new Date(payload.data?.fromDate),
          new Date(payload.data?.toDate),
        );
        this.pickingTimeScale = convertedInterval.scale;
        this.pickingTimeMin = convertedInterval.min;
        this.pickingTimeMax = convertedInterval.max;
        this.fetchPickingOrderData();

        localStorage.removeItem(redirectSessionKey); // Clean up after use
      } catch (error) {
        console.error('Failed to parse redirect session', error);
        localStorage.removeItem(redirectSessionKey); // Cleanup corrupted entry
      }
    },

    convertStartEndInterval(
      start: Date,
      end: Date,
      now: Date = new Date(),
    ): IntervalResult {
      const diffStartMs = Math.abs(start.getTime() - now.getTime());
      const diffEndMs = Math.abs(end.getTime() - now.getTime());

      const diffStartHours = diffStartMs / (1000 * 60 * 60);
      const diffEndHours = diffEndMs / (1000 * 60 * 60);

      const diffStartDays = diffStartHours / 24;
      const diffEndDays = diffEndHours / 24;

      const diffStartWeeks = diffStartDays / 7;
      const diffEndWeeks = diffEndDays / 7;

      // Prefer the largest unit possible
      if (diffStartWeeks >= 1 || diffEndWeeks >= 1) {
        return {
          scale: 'weeks',
          min: Math.floor(diffStartWeeks),
          max: Math.ceil(diffEndWeeks),
        };
      }
      if (diffEndDays >= 1 || diffStartDays >= 1) {
        return {
          scale: 'days',
          min: Math.floor(diffStartDays),
          max: Math.ceil(diffEndDays),
        };
      }
      return {
        scale: 'hours',
        min: Math.floor(diffStartHours),
        max: Math.ceil(diffEndHours),
      };
    },

