export const useUserAttributesStore = defineStore('userAttributes', {
  actions: {
    setUserAttributes(attributes: Array<UserAttribute>) {
      const transformedAttributes =
        this.transformAttributesToStorageFormat(attributes);
      this.userAttributes = transformedAttributes;
    },
    transformAttributesToStorageFormat(attributes: Array<UserAttribute>): {
      [key: string]: string;
    } {
      const transformed: { [key: string]: string } = {};
      for (const attribute of attributes) {
        transformed[attribute.userAttributeName] = attribute.value;
      }
      return transformed;
    },
  },
  persist: true,
  state: () => ({
    userAttributes: {} as { [key: string]: string },
  }),
});

