import { CloseShopOrderResponse } from '../../../types/close-shop-order-response-type.ts';
import * as api from '../service/api.ts';

const useWkStore = defineStore({
  actions: {
    async createAlert(pickingOrderIdsList = ''): Promise<{
      responses: Array<CloseShopOrderResponse>;
      errorArray: Array<string>;
      successCount: number;
    }> {
      const response = await (pickingOrderIdsList === ''
        ? api.createAlert(this.pickingOrderId)
        : api.createAlert(pickingOrderIdsList));

      // Ensure response.data is always an array
      const responseData = Array.isArray(response.data)
        ? response.data
        : [response.data];

      const errorArray: Array<string> = [];
      let successCount = 0;

      // Iterate through the responses safely
      for (const order of responseData) {
        if (
          order.statusCode.toUpperCase() !== 'SUCCESS' &&
          order.pickingOrderId
        ) {
          errorArray.push(order.pickingOrderId);
        }
        if (order.statusCode.toUpperCase() === 'SUCCESS') {
          successCount += 1;
        }
      }
      return {
        errorArray,
        responses: responseData,
        successCount,
      };
    },
  },
  id: 'useWkStore',

  state: () => ({
    pickingOrderId: ref(),
  }),
});

export default useWkStore;

