/**
 * Update filter preferences based on the provided table name and preferences list.
 * @param tableName - The name of the table.
 * @param filterPreferencesList - The list of user preferences for filters.
 * @param context - The context containing the current filter state and methods.
 */
export function updateFilterPreferencesHelper(
  tableName: string,
  filterPreferencesList: Array<UserPreference>,
  context: FilterContext,
): void {
  for (const pref of filterPreferencesList) {
    switch (pref.object) {
      case `workcenter_${tableName}`: {
        context.addDataToSelectedList(
          pref.addData,
          context.workCentersSelected,
        );
        break;
      }
      case `sfgWorkcenter_${tableName}`: {
        context.addDataToSelectedList(
          pref.addData,
          context.sfgWorkCentersSelected,
        );
        break;
      }
      case `material_${tableName}`: {
        context.addDataToSelectedList(pref.addData, context.materialsSelected);
        break;
      }
      case `srcLoc_${tableName}`: {
        context.addDataToSelectedList(pref.addData, context.srcLocsSelected);
        break;
      }
      case `hustrLoc_${tableName}`: {
        context.addDataToSelectedList(
          pref.addData,
          context.huCurStrLocSelected,
        );
        break;
      }
      case `destLocs_${tableName}`: {
        context.addDataToSelectedList(pref.addData, context.destLocsSelected);
        break;
      }
      case `custStatus_${tableName}`: {
        context.addDataToSelectedList(pref.addData, context.custStatusSelected);
        break;
      }
      case `pickingStatus_${tableName}`: {
        context.addDataToSelectedList(
          pref.addData,
          context.pickingStatusSelected,
        );
        break;
      }
      case `cstr_${tableName}`: {
        context.addDataToSelectedList(pref.addData, context.cstr);
        break;
      }
      case `otbDlr_${tableName}`: {
        context.addDataToSelectedList(pref.addData, context.otbDlr);
        break;
      }
      case `tpaNum_${tableName}`: {
        context.addDataToSelectedList(pref.addData, context.tpaNum);
        break;
      }
      case `tpaCodes_${tableName}`: {
        context.addDataToSelectedList(pref.addData, context.tpaCodesSelected);
        break;
      }
      case `endProdTimeType_${tableName}`: {
        context.endProdTimeType = pref.addData;
        break;
      }
      case `pickingTimeScale_${tableName}`: {
        context.pickingTimeScale = pref.addData;
        break;
      }
      case `pickingTimeMin_${tableName}`: {
        context.pickingTimeMin = Number.parseFloat(pref.addData);
        break;
      }
      case `pickingTimeMax_${tableName}`: {
        context.pickingTimeMax = Number.parseFloat(pref.addData);
        break;
      }
      case `hourinFuture_${tableName}`: {
        context.hourinFuture = pref.addData;
        break;
      }
      case `hourinFutureEnd_${tableName}`: {
        context.hourinFutureEnd = pref.addData;
        break;
      }
      case `startPreparationType_${tableName}`: {
        context.startPreparationType = pref.addData;
        break;
      }
      case `startPreparationTime_${tableName}`: {
        context.startPreparationTime = pref.addData;
        break;
      }
      case `endPreparationType_${tableName}`: {
        context.endPreparationType = pref.addData;
        break;
      }
      case `endPreparationDate_${tableName}`: {
        context.endPreparationDate = pref.addData;
        break;
      }
      case `truckDepartureType_${tableName}`: {
        context.truckDepartureType = pref.addData;
        break;
      }
      case `truckDepartureDate_${tableName}`: {
        context.truckDepartureDate = pref.addData;
        break;
      }
      case `promiseTime_${tableName}`: {
        context.promiseTime = pref.addData;
        break;
      }
      case `alert_${tableName}`: {
        context.alert = pref.addData;
        break;
      }
      case `rescheduled_${tableName}`: {
        context.rescheduled = pref.addData;
        break;
      }
      case `endProdDate_${tableName}`: {
        context.endProdDate = pref.addData;
        break;
      }
      default: {
        break;
      }
    }
  }
}

/* eslint-disable import/prefer-default-export */
/**
 *
 * @param  inNewPicking - The input date string to be formatted.
 * @returns The formatted date string in ISO 8601 format.
 */
export function formatDate(inNewPicking: string) {
  const myDate = new Date(Date.parse(inNewPicking));
  const year = myDate.getFullYear();
  const month = (myDate.getMonth() + 1).toString().padStart(2, '0');
  const day = myDate.getDate().toString().padStart(2, '0');
  const hours = myDate.getHours().toString().padStart(2, '0');
  const minutes = myDate.getMinutes().toString().padStart(2, '0');
  const iso8601String = `${year}-${month}-${day}T${hours}:${minutes}:00`;
  return iso8601String;
}

class AppLogger {
  log(message: unknown): void {
    /* eslint class-methods-use-this: "off" */
    /* eslint no-console: "off" */
    console.log(`${new Date().toISOString()} -- ${message}`);
  }

  error(message: unknown, stack?: string): void {
    /* eslint class-methods-use-this: "off" */
    /* eslint no-console: "off" */
    console.error(`${new Date().toISOString()} -- ${message}`, stack);
  }

  warn(message: unknown): void {
    /* eslint class-methods-use-this: "off" */
    /* eslint no-console: "off" */
    console.warn(`${new Date().toISOString()} -- ${message}`);
  }

  debug(message: unknown): void {
    /* eslint class-methods-use-this: "off" */
    /* eslint no-console: "off" */
    console.debug(`${new Date().toISOString()} -- ${message}`);
  }

  verbose(message: unknown): void {
    /* eslint class-methods-use-this: "off" */
    /* eslint no-console: "off" */
    console.info(`${new Date().toISOString()} -- ${message}`);
  }
}

export default new AppLogger();

